import unittest

from src import service
from src.store import open_store


class UsersTest(unittest.TestCase):
    def setUp(self):
        self.conn = open_store()

    def tearDown(self):
        self.conn.close()

    def test_register_normalizes_email(self):
        user_id = service.register_user(self.conn, '  Carol@Example.Invalid ')
        row = service.lookup_user(self.conn, 'carol@example.invalid')
        self.assertEqual(row['id'], user_id)

    def test_lookup_with_mixed_case_currently_misses(self):
        # Current behavior: lookup_user does not normalize its input.
        self.assertIsNone(service.lookup_user(self.conn, 'Alice@Example.Invalid'))

    def test_view_user_enforces_can_view(self):
        with self.assertRaises(PermissionError):
            service.view_user(self.conn, {'id': 1, 'is_admin': 0}, 2)


if __name__ == '__main__':
    unittest.main()
import unittest

from src.store import open_store


class SchemaTest(unittest.TestCase):
    def setUp(self):
        self.conn = open_store()

    def tearDown(self):
        self.conn.close()

    def test_users_columns(self):
        cols = [row['name'] for row in self.conn.execute('PRAGMA table_info(users)')]
        self.assertEqual(cols, ['id', 'email', 'is_admin', 'last_seen'])

    def test_last_seen_index_exists(self):
        names = [row['name'] for row in self.conn.execute('PRAGMA index_list(users)')]
        self.assertIn('idx_users_last_seen', names)

    def test_seed_rows(self):
        self.assertEqual(self.conn.execute('SELECT COUNT(*) FROM users').fetchone()[0], 3)


if __name__ == '__main__':
    unittest.main()
